#!/bin/bash
# GRAVITY NAS ALL-IN-ONE INSTALLER
NAS_DIR="/opt/gravitynas"

echo "------------------------------------------"
echo "   INSTALLATION AUTOMATIQUE GRAVITY NAS   "
echo "------------------------------------------"

echo "[1/4] Nettoyage et préparation..."
sudo systemctl stop gravitynas 2>/dev/null || true
sudo find $NAS_DIR -mindepth 1 -maxdepth 1 ! -name "data" ! -name "nas_storage" -exec rm -rf {} +
sudo mkdir -p $NAS_DIR
sudo chown $(id -un):$(id -un) $NAS_DIR

echo "[2/4] Extraction des fichiers sources..."
echo "" | base64 -d | tar -xzC $NAS_DIR

echo "[3/4] Installation des composants système..."
sudo apt-get update -qq
sudo apt-get install -y -qq python3-full python3-pip python3-venv nginx avahi-daemon samba > /dev/null

echo "[4/4] Configuration et démarrage..."
cd $NAS_DIR
python3 -m venv venv
./venv/bin/pip install --upgrade pip -q
if [ -f "requirements.txt" ]; then
    ./venv/bin/pip install -r requirements.txt -q
fi

sudo bash -c "cat > /etc/systemd/system/gravitynas.service" << EOT
[Unit]
Description=GravityNAS
After=network.target

[Service]
ExecStart=$NAS_DIR/venv/bin/python $NAS_DIR/main.py
Restart=always
User=$(id -un)
WorkingDirectory=$NAS_DIR
Environment=PYTHONUNBUFFERED=1

[Install]
WantedBy=multi-user.target
EOT

sudo systemctl daemon-reload
sudo systemctl enable gravitynas
sudo systemctl start gravitynas

echo "------------------------------------------"
echo "✅ TERMINÉ ! Le serveur tourne en arrière-plan."
echo "Accès : http://gravitynas.local"
echo "------------------------------------------"
